1	package main
2	
3	import (
4		"crypto/sha256"
5		_ "embed"
6		"encoding/json"
7		"fmt"
8		"io"
9		"net/http"
10		"net/url"
11		"os"
12		"strings"
13		"sync"
14		"time"
15	)
16	
17	//go:embed web/index.html
18	var indexHTML []byte
19	
20	type order struct {
21		ID         string `json:"id"`
22		Customer   string `json:"customer"`
23		Amount     int    `json:"amount"`
24		Reason     string `json:"reason"`
25		Status     string `json:"status"`
26		Note       string `json:"note,omitempty"`
27		ReviewedAt string `json:"reviewedAt,omitempty"`
28	}
29	
30	type reviewRequest struct {
31		Decision string `json:"decision"`
32		Note     string `json:"note"`
33	}
34	
35	// evidenceReference is one supporting reference a reviewer attaches to an
36	// order exception (REQ-002): a label and an http(s) link, kept in memory next
37	// to the order. Nothing is uploaded or stored; only the link is remembered.
38	type evidenceReference struct {
39		Label   string `json:"label"`
40		URL     string `json:"url"`
41		AddedAt string `json:"addedAt"`
42	}
43	
44	type evidenceRequest struct {
45		Label string `json:"label"`
46		URL   string `json:"url"`
47	}
48	
49	// maxEvidencePerOrder caps the references on one order (AC-002).
50	const maxEvidencePerOrder = 3
51	
52	// orderView is what GET /api/orders returns: the order plus its evidence
53	// references (AC-004). The references live outside `order` so that existing
54	// review behaviour and its tests stay untouched (AC-005).
55	type orderView struct {
56		order
57		Evidence []evidenceReference `json:"evidence"`
58	}
59	
60	type server struct {
61		mu          sync.RWMutex
62		environment string
63		revision    string
64		buildDigest string
65		startedAt   string
66		orders      map[string]*order
67		evidence    map[string][]evidenceReference
68	}
69	
70	// newServer builds the in-memory portal. The environment label is read from
71	// ORDER_PORTAL_ENV so two local instances (DR-015: local staging and local
72	// prod-demo) can be told apart from their own /healthz read-back, not only from
73	// the port they were started on. The revision and build digest give a local
74	// instance the two identities a Cloud Run revision has: which build is
75	// running (digest of this executable) and which start of it answers
76	// (revision, new on every process start).
77	func newServer() *server {
78		started := time.Now().UTC()
79		environment := environmentLabel(os.Getenv("ORDER_PORTAL_ENV"))
80		return &server{
81			environment: environment,
82			revision:    revisionName(environment, started, os.Getpid()),
83			buildDigest: processDigest(),
84			startedAt:   started.Format(time.RFC3339),
85			orders: map[string]*order{
86				"ORD-1001": {ID: "ORD-1001", Customer: "Acme North", Amount: 12800, Reason: "Shipping address changed after payment", Status: "PENDING_REVIEW"},
87				"ORD-1002": {ID: "ORD-1002", Customer: "Beta Studio", Amount: 4200, Reason: "High-value order needs a second check", Status: "PENDING_REVIEW"},
88			},
89			evidence: map[string][]evidenceReference{},
90		}
91	}
92	
93	func (s *server) routes() http.Handler {
94		mux := http.NewServeMux()
95		mux.HandleFunc("GET /", s.home)
96		mux.HandleFunc("GET /healthz", s.health)
97		mux.HandleFunc("GET /api/orders", s.listOrders)
98		mux.HandleFunc("POST /api/orders/", s.orderAction)
99		return logging(mux)
100	}
101	
102	// orderAction dispatches POST /api/orders/{id}/review and
103	// POST /api/orders/{id}/evidence; anything else under the prefix is 404.
104	func (s *server) orderAction(w http.ResponseWriter, r *http.Request) {
105		parts := strings.Split(strings.Trim(r.URL.Path, "/"), "/")
106		if len(parts) != 4 || parts[0] != "api" || parts[1] != "orders" {
107			http.NotFound(w, r)
108			return
109		}
110		switch parts[3] {
111		case "review":
112			s.review(w, r, parts[2])
113		case "evidence":
114			s.addEvidence(w, r, parts[2])
115		default:
116			http.NotFound(w, r)
117		}
118	}
119	
120	func (s *server) home(w http.ResponseWriter, r *http.Request) {
121		w.Header().Set("Content-Type", "text/html; charset=utf-8")
122		_, _ = w.Write(indexHTML)
123	}
124	
125	func (s *server) health(w http.ResponseWriter, r *http.Request) {
126		writeJSON(w, http.StatusOK, map[string]string{
127			"status": "ok", "service": "order-operations-portal", "environment": s.environment,
128			"revision": s.revision, "build_digest": s.buildDigest, "started_at": s.startedAt,
129		})
130	}
131	
132	// revisionName is unique per process start, like a Cloud Run revision is
133	// unique per deployment: <environment>-<start time>-<pid>. Restarting the
134	// same binary yields a new revision; the build digest is what stays equal.
135	// The label is reduced to [a-z0-9-] so an odd ORDER_PORTAL_ENV cannot put
136	// spaces, slashes or control characters into the revision.
137	func revisionName(environment string, started time.Time, pid int) string {
138		return fmt.Sprintf("%s-%s-%d", revisionLabel(environment), started.Format("20060102t150405z"), pid)
139	}
140	
141	func revisionLabel(environment string) string {
142		label := strings.Map(func(r rune) rune {
143			switch {
144			case r >= 'a' && r <= 'z', r >= '0' && r <= '9', r == '-':
145				return r
146			case r >= 'A' && r <= 'Z':
147				return r + ('a' - 'A')
148			default:
149				return '-'
150			}
151		}, environment)
152		if label = strings.Trim(label, "-"); label == "" {
153			return "local"
154		}
155		return label
156	}
157	
158	// processDigest hashes the executable once per process: every server in the
159	// process runs the same file, so later calls reuse the first result.
160	var processDigest = sync.OnceValue(executableDigest)
161	
162	// executableDigest hashes the running executable so the read-back can tell
163	// which build answers, without a container registry. It is a binary digest,
164	// not an OCI image digest; an empty string means it could not be read. It
165	// hashes the file at os.Executable(), so a binary replaced on disk between
166	// exec and the first call would be misreported; there is no portable way to
167	// hash the mapped image instead (macOS has no /proc/self/exe).
168	func executableDigest() string {
169		path, err := os.Executable()
170		if err != nil {
171			return ""
172		}
173		file, err := os.Open(path)
174		if err != nil {
175			return ""
176		}
177		defer file.Close()
178		hash := sha256.New()
179		if _, err := io.Copy(hash, file); err != nil {
180			return ""
181		}
182		return fmt.Sprintf("sha256:%x", hash.Sum(nil))
183	}
184	
185	// environmentLabel normalises ORDER_PORTAL_ENV; an unset value reports "local"
186	// so a single-instance run is still distinguishable from a labelled one.
187	func environmentLabel(raw string) string {
188		if label := strings.TrimSpace(raw); label != "" {
189			return label
190		}
191		return "local"
192	}
193	
194	// listenAddr honours PORT (Cloud Run convention, also what ContextRail itself
195	// reads) and falls back to :8080 so the documented `go run .` keeps working.
196	func listenAddr(port string) string {
197		if port = strings.TrimSpace(port); port != "" {
198			return ":" + port
199		}
200		return ":8080"
201	}
202	
203	// orderStatuses are the only values an order's status can take: the initial
204	// PENDING_REVIEW and the two review decisions.
205	var orderStatuses = []string{"PENDING_REVIEW", "APPROVED", "REJECTED"}
206	
207	// validOrderStatus reports whether raw is one of orderStatuses, compared
208	// exactly (no trimming or case folding) so the filter matches the stored value.
209	func validOrderStatus(raw string) bool {
210		for _, status := range orderStatuses {
211			if raw == status {
212				return true
213			}
214		}
215		return false
216	}
217	
218	// listOrders returns every order, or only the orders in one status when the
219	// `status` query parameter is present (AWO-001). A status parameter that is
220	// not one of orderStatuses is a 400 with a JSON error; no parameter at all
221	// keeps the previous behaviour of listing everything.
222	func (s *server) listOrders(w http.ResponseWriter, r *http.Request) {
223		query := r.URL.Query()
224		filter := query.Get("status")
225		if query.Has("status") && !validOrderStatus(filter) {
226			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "status must be " + strings.Join(orderStatuses, ", ")})
227			return
228		}
229		s.mu.RLock()
230		defer s.mu.RUnlock()
231		result := make([]orderView, 0, len(s.orders))
232		for _, item := range s.orders {
233			if filter != "" && item.Status != filter {
234				continue
235			}
236			result = append(result, orderView{order: *item, Evidence: s.evidenceOf(item.ID)})
237		}
238		writeJSON(w, http.StatusOK, result)
239	}
240	
241	// evidenceOf returns a copy of the order's references, never nil, so the JSON
242	// always carries an `evidence` array. Callers hold s.mu.
243	func (s *server) evidenceOf(orderID string) []evidenceReference {
244		return append([]evidenceReference{}, s.evidence[orderID]...)
245	}
246	
247	// decodeSingleJSON reads exactly one JSON object from the body; anything
248	// malformed or trailing is a 400 with a JSON error (same rule as review).
249	func decodeSingleJSON(w http.ResponseWriter, r *http.Request, target any) bool {
250		decoder := json.NewDecoder(r.Body)
251		if err := decoder.Decode(target); err != nil {
252			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request must be valid JSON"})
253			return false
254		}
255		var trailing any
256		if err := decoder.Decode(&trailing); err != io.EOF {
257			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request must contain one JSON object"})
258			return false
259		}
260		return true
261	}
262	
263	func (s *server) review(w http.ResponseWriter, r *http.Request, orderID string) {
264		var req reviewRequest
265		if !decodeSingleJSON(w, r, &req) {
266			return
267		}
268		if req.Decision != "APPROVED" && req.Decision != "REJECTED" {
269			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "decision must be APPROVED or REJECTED"})
270			return
271		}
272		if strings.TrimSpace(req.Note) == "" {
273			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "note is required"})
274			return
275		}
276		s.mu.Lock()
277		defer s.mu.Unlock()
278		item, ok := s.orders[orderID]
279		if !ok {
280			writeJSON(w, http.StatusNotFound, map[string]string{"error": "order not found"})
281			return
282		}
283		item.Status = req.Decision
284		item.Note = strings.TrimSpace(req.Note)
285		item.ReviewedAt = time.Now().UTC().Format(time.RFC3339)
286		writeJSON(w, http.StatusOK, map[string]any{"order": item, "reviewedAt": item.ReviewedAt})
287	}
288	
289	// addEvidence attaches one evidence reference to an order (REQ-002).
290	// AC-001: label and http(s) URL required → otherwise 400 JSON error.
291	// AC-002: the fourth reference on the same order → 409.
292	// AC-003: unknown order → 404.
293	func (s *server) addEvidence(w http.ResponseWriter, r *http.Request, orderID string) {
294		var req evidenceRequest
295		if !decodeSingleJSON(w, r, &req) {
296			return
297		}
298		label := strings.TrimSpace(req.Label)
299		if label == "" {
300			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "label is required"})
301			return
302		}
303		link, err := validEvidenceURL(req.URL)
304		if err != nil {
305			writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
306			return
307		}
308		s.mu.Lock()
309		defer s.mu.Unlock()
310		if _, ok := s.orders[orderID]; !ok {
311			writeJSON(w, http.StatusNotFound, map[string]string{"error": "order not found"})
312			return
313		}
314		if len(s.evidence[orderID]) >= maxEvidencePerOrder {
315			writeJSON(w, http.StatusConflict, map[string]string{"error": fmt.Sprintf("order already has %d evidence references", maxEvidencePerOrder)})
316			return
317		}
318		reference := evidenceReference{Label: label, URL: link, AddedAt: time.Now().UTC().Format(time.RFC3339)}
319		s.evidence[orderID] = append(s.evidence[orderID], reference)
320		writeJSON(w, http.StatusCreated, map[string]any{"order": orderID, "evidence": s.evidenceOf(orderID)})
321	}
322	
323	// validEvidenceURL accepts only absolute http or https links with a host; the
324	// link is remembered as given (trimmed), never fetched.
325	func validEvidenceURL(raw string) (string, error) {
326		raw = strings.TrimSpace(raw)
327		if raw == "" {
328			return "", fmt.Errorf("url is required")
329		}
330		parsed, err := url.Parse(raw)
331		if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") || parsed.Host == "" {
332			return "", fmt.Errorf("url must be an absolute http or https link")
333		}
334		return raw, nil
335	}
336	
337	func writeJSON(w http.ResponseWriter, status int, value any) {
338		w.Header().Set("Content-Type", "application/json")
339		w.WriteHeader(status)
340		_ = json.NewEncoder(w).Encode(value)
341	}
342	
343	func logging(next http.Handler) http.Handler {
344		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
345			fmt.Printf("%s %s\n", r.Method, r.URL.Path)
346			next.ServeHTTP(w, r)
347		})
348	}
349	
350	func main() {
351		addr := listenAddr(os.Getenv("PORT"))
352		fmt.Printf("order-operations-portal listening on %s (environment=%s)\n", addr, environmentLabel(os.Getenv("ORDER_PORTAL_ENV")))
353		_ = http.ListenAndServe(addr, newServer().routes())
354	}
