455			t.Fatalf("started_at must be reported")
456		}
457		// The same build answers with the same digest; a new start is a new revision.
458		again := newServer()
459		if again.buildDigest != s.buildDigest {
460			t.Fatalf("build digest must be stable for one executable: %q vs %q", again.buildDigest, s.buildDigest)
461		}
462		if revisionName("prod-demo", time.Date(2026, 10, 26, 1, 2, 3, 0, time.UTC), 42) != "prod-demo-20261026t010203z-42" {
463			t.Fatalf("unexpected revision format: %s", revisionName("prod-demo", time.Date(2026, 10, 26, 1, 2, 3, 0, time.UTC), 42))
464		}
465	}
466	
467	// independentExecutableDigest recomputes the digest without executableDigest so
468	// the test fails if that helper hashes the wrong file or a constant.
469	func independentExecutableDigest(t *testing.T) string {
470		t.Helper()
471		path, err := os.Executable()
472		if err != nil {
473			t.Fatalf("os.Executable: %v", err)
474		}
475		file, err := os.Open(path)
476		if err != nil {
477			t.Fatalf("open executable: %v", err)
478		}
479		defer file.Close()
480		hash := sha256.New()
481		if _, err := io.Copy(hash, file); err != nil {
482			t.Fatalf("hash executable: %v", err)
483		}
484		return fmt.Sprintf("sha256:%x", hash.Sum(nil))
485	}
486	
487	func TestRevisionLabelIsSanitised(t *testing.T) {
488		cases := map[string]string{"staging": "staging", "Prod Demo": "prod-demo", "a/b\nc": "a-b-c", "--": "local", "": "local"}
489		for in, want := range cases {
490			if got := revisionLabel(in); got != want {
491				t.Fatalf("revisionLabel(%q) = %q, want %q", in, got, want)
492			}
493		}
494	}
495	
496	// TestRestartIsANewRevision starts this test binary twice as a real process
497	// (the helper below prints one /healthz body) and checks that the two starts
498	// report different revisions and the same build digest. The two starts usually
499	// land in the same second, so it is the pid part that separates them.
500	func TestRestartIsANewRevision(t *testing.T) {
501		if os.Getenv("ORDER_PORTAL_HEALTH_HELPER") == "1" {
502			t.Skip("helper process")
503		}
504		var bodies [2]map[string]string
505		for i := range bodies {
506			cmd := exec.Command(os.Args[0], "-test.run=^TestHealthHelperProcess$")
507			cmd.Env = append(os.Environ(), "ORDER_PORTAL_HEALTH_HELPER=1", "ORDER_PORTAL_ENV=staging")
508			out, err := cmd.Output()
509			if err != nil {
510				t.Fatalf("start %d: %v", i+1, err)
511			}
512			line, _, _ := strings.Cut(string(out), "\n")
513			if err := json.Unmarshal([]byte(line), &bodies[i]); err != nil {
514				t.Fatalf("start %d: decode %q: %v", i+1, line, err)
515			}
516		}
517		if bodies[0]["revision"] == "" || bodies[0]["revision"] == bodies[1]["revision"] {
518			t.Fatalf("two starts must report different revisions: %q vs %q", bodies[0]["revision"], bodies[1]["revision"])
519		}
520		if bodies[0]["build_digest"] == "" || bodies[0]["build_digest"] != bodies[1]["build_digest"] {
521			t.Fatalf("two starts of one binary must report the same digest: %q vs %q", bodies[0]["build_digest"], bodies[1]["build_digest"])
522		}
523	}
524	
525	func TestHealthHelperProcess(t *testing.T) {
526		if os.Getenv("ORDER_PORTAL_HEALTH_HELPER") != "1" {
527			t.Skip("only runs as the helper process of TestRestartIsANewRevision")
528		}
529		res := httptest.NewRecorder()
530		newServer().health(res, httptest.NewRequest(http.MethodGet, "/healthz", nil)) // health directly: the logging middleware would print first
531		fmt.Print(res.Body.String())
532	}
